#!/bin/sh
# SCHEM-LVS-01 capture driver, generated by tools/golden/authoring/schem_cases.py (m8-schematic design D16).
# 1. xschem: LVS netlist of the Hefesto-drawn inv_1.sch. 2. Magic: extract sky130_fd_sc_hd__inv_1 for LVS.
# 3. netgen: compare the two with the PDK's setup file. Each step prints its exit status; the driver exits
# with the last non-zero.
status=0
mkdir -p out
step() {
  label=$1; shift
  echo "== $label"; echo "== $label" >&2
  "$@"; rc=$?
  echo "== $label: exit $rc"
  if [ "$rc" -ne 0 ]; then status=$rc; fi
}
step xschem xschem -q -x -r --rcfile /work/input/xschemrc -n -s -o /work/out \
  --tcl 'set lvs_netlist 1; set lvs_ignore 1' /work/input/inv_1.sch
cd out
step magic magic -dnull -noconsole -T /work/input/sky130A.tech /work/input/extract.tcl
step netgen netgen -batch lvs "sky130_fd_sc_hd__inv_1.spice sky130_fd_sc_hd__inv_1" "inv_1.spice inv_1" \
  /work/input/sky130A_setup.tcl lvs.out
cd ..
exit "$status"
